# -*- coding: utf-8 -*-
"""Meteorology B: Foundation (F) and Bridge (B) questions, topics obs, maps, upper, setup, clouds."""
import sys,os
sys.path.insert(0,os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','src_geo'))
from auth import *
def run():
    # ---------------- obs: observation tools ----------------
    t='obs'
    SA(t,'F',"Which tool measures how hot or cold the air is?",["thermometer"],["A thermometer measures temperature.","Common units are degrees Fahrenheit (°F) and degrees Celsius (°C)."])
    SA(t,'F',"Which tool shows the direction the wind is blowing from?",["wind vane","weather vane","weathervane"],["A wind vane has a tail that swings around.","The pointer faces into the wind, so it shows where the wind comes FROM."])
    SA(t,'F',"Which tool measures how fast the wind is blowing?",["anemometer"],["Spinning cups catch the wind.","The faster they spin, the faster the wind. The tool is an anemometer."])
    SA(t,'F',"Which tool measures how much rain has fallen?",["rain gauge","rain guage"],["A rain gauge is a tube that catches rain.","You read how deep the water is."])
    SA(t,'F',"Which tool measures air pressure?",["barometer"],["Air has weight, and a barometer measures how hard it pushes.","The name comes from the Greek word baros, meaning weight."])
    SA(t,'F',"Which tool measures how much water vapor is in the air?",["hygrometer","psychrometer"],["Hygro means wet or moist.","A hygrometer measures humidity."])
    SA(t,'F',"A wind vane points toward the west. Which direction is the wind coming from?",["west","from the west","w"],["Wind is named for where it comes FROM.","The vane points into the wind, so this is a west wind."])
    SA(t,'F',"The instrument package carried up by a weather balloon is called a…",["radiosonde"],["The balloon lifts a small box of sensors.","The box (a radiosonde) measures temperature, pressure and humidity and radios the data down."])
    SA(t,'F',"Cloud photos taken from space come from a weather…",["satellite"],["Satellites orbit Earth and take pictures of clouds.","They help forecasters see storms over oceans where there are few stations."])
    NM(t,'F',"A rain gauge collects 2.5 cm of rain on Monday and 1.5 cm on Tuesday. How many centimeters of rain is that in all?",4,["Add the two days: 2.5 + 1.5 = 4.0.","The total is 4 cm."],u='cm',free=True)
    NM(t,'F',"A thermometer reads 20 °C in the morning and 28 °C in the afternoon. By how many degrees did it rise?",8,["Subtract: 28 − 20 = 8.","It rose 8 °C."],u='°C',free=True)
    SA(t,'F',"What is the word for the layer of gases that surrounds Earth?",["atmosphere"],["Weather happens in the atmosphere.","Meteorology is the study of the atmosphere."])
    NM(t,'B',"Convert 25 °C to degrees Fahrenheit. (°F = 9/5 × °C + 32)",77,["9/5 × 25 = 45.","45 + 32 = 77 °F."],u='°F',free=True)
    NM(t,'B',"Convert 50 °F to degrees Celsius. (°C = 5/9 × (°F − 32))",10,["50 − 32 = 18.","5/9 × 18 = 10 °C."],u='°C',free=True)
    NM(t,'B',"Convert 20 °C to kelvins. (K = °C + 273)",293,["Add 273: 20 + 273 = 293.","20 °C is 293 K. Kelvin has no negative values."],u='K',free=True)
    NM(t,'B',"A wind of 20 knots is about how many mph? (1 knot ≈ 1.15 mph)",23,["Multiply: 20 × 1.15 = 23.","20 knots ≈ 23 mph."],u='mph',free=True)
    NM(t,'B',"A rain gauge has a narrow measuring tube with one-tenth the area of its funnel, so the water is 10 times deeper in the tube. The tube shows 0.50 cm of water. How many cm of rain actually fell?",0.05,["The tube makes depth 10 times larger, so divide the reading by 10.","0.50 ÷ 10 = 0.05 cm."],u='cm',free=True,adj=0.2)
    SA(t,'B',"What does the Z in a time such as 12Z stand for?",["zulu","zulu time","utc","coordinated universal time","greenwich mean time","gmt"],["Weather data worldwide uses one clock so reports line up.","Z means Zulu time, which is the same as UTC."])
    SA(t,'B',"Radiosondes are launched at the same two times each day around the world. Which two UTC times?",["00z and 12z","0000 and 1200","00 and 12","00z, 12z","00z and 12z utc","0z and 12z"],["Launches are timed so every station reports at once.","The times are 00Z and 12Z."],adj=0.1)
    SA(t,'B',"Which kind of satellite stays above one point on the equator: geostationary or polar-orbiting?",["geostationary"],["A geostationary satellite orbits at the same rate Earth turns.","So it hovers over one spot and can watch the same area all the time."])
    SA(t,'B',"What instrument uses a laser or light beam to measure the height of the cloud base?",["ceilometer"],["Ceilo means ceiling, the height of the lowest cloud layer.","A ceilometer measures it."])
    NM(t,'B',"A storm center reads 28.50 inches of mercury. Convert to hectopascals. (1 inHg ≈ 33.86 hPa)",965,["Multiply: 28.50 × 33.86.","28.50 × 33.86 ≈ 965 hPa, a very low pressure."],u='hPa',free=True,adj=0.2)
    SA(t,'B',"Doppler radar measures the motion of raindrops along the radar beam. What is this speed called?",["radial velocity","velocity","radial speed"],["Doppler radar sees whether drops move toward or away from the radar.","That motion along the beam is the radial velocity."],adj=0.2)
    SA(t,'B',"A barometer reading that falls quickly over a few hours usually means the weather is about to get…",["worse","stormier","get worse","stormy","deteriorate"],["Falling pressure means a low-pressure system is approaching.","Lows bring clouds, wind and precipitation."])
    # ---------------- maps ----------------
    t='maps'
    SA(t,'F',"On a weather map, what does a large letter H mean?",["high pressure","high"],["H marks a center of high pressure.","High pressure usually brings clear, calm weather."])
    SA(t,'F',"On a weather map, what does a large letter L mean?",["low pressure","low"],["L marks a center of low pressure.","Low pressure usually brings clouds and storms."])
    SA(t,'F',"Lines on a weather map that connect places with equal air pressure are called…",["isobars","isobar"],["Iso means equal and bar means pressure.","So these lines are isobars."])
    SA(t,'F',"Lines on a weather map that connect places with equal temperature are called…",["isotherms","isotherm"],["Iso means equal and therm means heat.","So these lines are isotherms."])
    SA(t,'F',"A blue line with triangles on a weather map shows which kind of front?",["cold front","cold"],["Blue is for cold air.","Blue lines with triangles are cold fronts."])
    SA(t,'F',"A red line with half-circles on a weather map shows which kind of front?",["warm front","warm"],["Red is for warm air.","Red lines with half-circles are warm fronts."])
    SA(t,'F',"On a station model, a completely filled-in circle means the sky is…",["overcast","covered","cloudy","fully cloudy"],["The circle shows how much of the sky is covered by cloud.","A filled circle means all of it: overcast."])
    SA(t,'F',"On a station model, an empty circle means the sky is…",["clear","no clouds","sunny","cloudless"],["An empty circle means no cloud cover.","The sky is clear."])
    NM(t,'F',"On a map, 1 cm stands for 50 km. Two cities are 4 cm apart on the map. How many kilometers apart are they?",200,["Each centimeter is 50 km.","4 × 50 = 200 km."],u='km',free=True)
    SA(t,'F',"In the Northern Hemisphere, winds around a low-pressure center spin clockwise or counterclockwise?",["counterclockwise","counter-clockwise","anticlockwise","counter clockwise"],["Winds spiral in toward a low and turn because Earth spins.","In the Northern Hemisphere that turn is counterclockwise."])
    SA(t,'F',"In the Northern Hemisphere, winds around a high-pressure center spin clockwise or counterclockwise?",["clockwise"],["Highs spin the opposite way from lows.","In the Northern Hemisphere highs spin clockwise."])
    NM(t,'B',"A station model shows the pressure code 132. Add a leading 10 and put a decimal before the last digit. What is the pressure in hPa?",1013.2,["For codes starting with 0, 1 or 2, put 10 in front.","132 becomes 1013.2 hPa."],u='hPa',free=True,tol=0.001)
    NM(t,'B',"A station model shows the pressure code 987. For codes starting with 5 to 9, put a 9 in front and a decimal before the last digit. What is the pressure in hPa?",998.7,["The code starts with 9, so put a 9 in front: 9987.","Place the decimal before the last digit: 998.7 hPa."],u='hPa',free=True,tol=0.001)
    NM(t,'B',"A wind barb has one long barb and one short barb. What is the wind speed in knots? (long = 10, short = 5)",15,["Add the barbs: 10 + 5.","The wind is 15 knots."],u='kt',free=True)
    NM(t,'B',"A wind barb has one flag (pennant, 50 knots) and two long barbs (10 knots each). What is the wind speed in knots?",70,["The flag counts 50.","50 + 10 + 10 = 70 knots."],u='kt',free=True)
    NM(t,'B',"A METAR reports wind 29008KT. From what direction, in degrees, is the wind blowing?",290,["The first three digits are the direction wind comes from.","290° is a wind from the west-northwest."],u='°',free=True)
    SA(t,'B',"In a METAR, the group 18/09 gives temperature and dew point in °C. Which number is the dew point?",["09","9","9 degrees","09 degrees"],["Temperature comes first, then dew point.","The dew point is 09 °C, so the air is 9 °C from saturation."])
    SA(t,'B',"On a surface map, are winds stronger where isobars are close together or far apart?",["close together","closer","close","packed together","close together."],["Close isobars mean pressure changes quickly over a short distance.","A big pressure change over a short distance drives stronger wind."])
    CP(t,'B',"A station model has its wind staff pointing toward the northwest. The wind is blowing FROM the northwest. Drag the pointer to that direction.",315,["The staff points toward where the wind comes from.","Northwest is 315° (N = 0°, E = 90°, S = 180°, W = 270°)."])
    CP(t,'B',"The wind is blowing FROM the southeast. Drag the pointer to the direction the wind comes from.",135,["Southeast lies halfway between east (90°) and south (180°).","That is 135°."])
    NM(t,'B',"On a weather map, two stations are 2.5 cm apart and 1 cm equals 120 km. How far apart are the stations?",300,["Multiply the map distance by the scale: 2.5 × 120.","Distance = 300 km."],u='km',free=True)
    SA(t,'B',"A stationary front is drawn with alternating red half-circles and blue triangles on opposite sides. What does the front do?",["it does not move","stays in place","doesn't move","does not move much","stalls","stays put"],["Neither air mass is winning.","The boundary stays nearly in place."])
    # ---------------- upper: upper air, soundings, CAPE ----------------
    t='upper'
    SA(t,'F',"Near the ground, temperature usually gets warmer or cooler as you climb higher in the atmosphere?",["cooler","colder","gets cooler","gets colder","decreases"],["Higher up, the air is thinner and farther from the warm ground.","In the troposphere the temperature falls with height."])
    SA(t,'F',"What is the lowest layer of the atmosphere, where almost all weather happens?",["troposphere"],["Tropo means to turn or mix.","The troposphere is the layer we live in."])
    SA(t,'F',"A rising bubble of air is called an air…",["parcel"],["Forecasters imagine a small bubble of air.","They call it a parcel and follow it as it rises."])
    SA(t,'F',"Air pressure gets higher or lower as you climb up a mountain?",["lower","decreases","drops","decrease","gets lower"],["There is less air above you pressing down.","Pressure falls with height."])
    SA(t,'F',"When rising air cools enough, water vapor turns into tiny droplets. This change is called…",["condensation","condensing"],["Gas to liquid is condensation.","This is how clouds begin."])
    SA(t,'F',"A graph of temperature and moisture at different heights, made from a weather balloon, is called a…",["sounding","skew-t","profile","vertical profile"],["The balloon measures as it climbs.","The record of those measurements is called a sounding."])
    NM(t,'B',"The dry adiabatic lapse rate is about 10 °C per kilometer. A dry parcel at 25 °C rises 2 km. What is its new temperature?",5,["Cooling = 10 °C/km × 2 km = 20 °C.","25 − 20 = 5 °C."],u='°C',free=True)
    NM(t,'B',"A saturated parcel cools about 6 °C per km as it rises. How many degrees does it cool in 3 km?",18,["Multiply: 6 × 3.","The parcel cools 18 °C."],u='°C',free=True)
    NM(t,'B',"Estimate the lifting condensation level (cloud base) with 125 m × (T − Td). The surface temperature is 30 °C and the dew point is 18 °C. How high is the cloud base?",1500,["T − Td = 12 °C.","125 × 12 = 1500 m."],u='m',free=True)
    SA(t,'B',"A layer where temperature increases with height is called a(n)…",["inversion","temperature inversion","capping inversion"],["Normally air cools with height.","When it warms with height instead, that is an inversion."])
    SA(t,'B',"What does CAPE stand for?",["convective available potential energy"],["CAPE measures the energy stored for rising air.","Convective Available Potential Energy."],adj=0.1)
    SA(t,'B',"CAPE is measured in joules per what?",["kilogram","kg","joules per kilogram"],["It is energy per mass of air.","The unit is J/kg."])
    SA(t,'B',"Larger CAPE means a stronger or weaker possible updraft?",["stronger","strong","stronger updraft"],["CAPE is the energy that can lift a parcel.","More energy means stronger updrafts."])
    SA(t,'B',"A warm layer above the ground that stops rising air from reaching high levels is called a…",["cap","capping inversion","lid"],["It acts like a lid.","If the cap breaks, storms can explode."],adj=0.1)
    NM(t,'B',"On a sounding, the temperature is 20 °C at the surface and 4 °C at 2 km. What is the average lapse rate in °C per km?",8,["Temperature drop: 20 − 4 = 16 °C.","16 °C over 2 km is 8 °C per km."],u='°C/km',free=True)
    # ---------------- setup: jets, fronts, shear ----------------
    t='setup'
    SA(t,'F',"The boundary between two different air masses is called a…",["front"],["Air masses have different temperature and moisture.","Where they meet is a front."])
    SA(t,'F',"A large body of air with about the same temperature and moisture everywhere is an air…",["mass"],["It forms over one kind of region for days.","This is called an air mass."])
    SA(t,'F',"Which is denser, warm air or cold air?",["cold air","cold","cold air is denser"],["Cold air has molecules packed closer.","Cold air is denser, so it sinks under warm air."])
    SA(t,'F',"A fast river of wind high in the sky is called the…",["jet stream","jet"],["It is a narrow band of strong winds.","It steers storms across the country."])
    SA(t,'F',"Across the United States the jet stream mostly flows from which direction to which?",["west to east","from west to east","west"],["Most of the winds above the middle latitudes blow from the west.","So the jet stream flows west to east."])
    SA(t,'F',"A cold front arrives and cool air replaces warm air. What usually happens to the temperature?",["it drops","drops","falls","gets colder","decreases","cooler"],["Cold air is replacing warm air.","The temperature falls."])
    SA(t,'B',"Wind shear means the wind changes with…",["height","altitude","distance","height or distance"],["Shear is a change in wind speed or direction.","It is usually measured between two heights."])
    NM(t,'B',"The wind is 15 knots from the south at the surface and 55 knots from the south at 6 km. What is the wind speed shear in knots?",40,["Subtract: 55 − 15.","The speed shear is 40 knots."],u='kt',free=True)
    SA(t,'B',"A dryline separates moist air from what kind of air?",["dry","dry air","desert air","dry desert air"],["The dryline marks a sharp drop in dew point.","Moist Gulf air is on one side and dry desert air on the other."])
    SA(t,'B',"A low-level jet is strongest at what time of day?",["night","at night","overnight","nighttime"],["After sunset the surface layer decouples from the winds above.","Winds a few hundred meters up speed up, especially at night."],adj=0.1)
    SA(t,'B',"Does strong wind shear tend to organize thunderstorms (such as supercells) or tear them apart?",["organize","organize them","organizes","organizes them"],["Moderate to strong shear tilts the updraft.","Rain falls away from the updraft, so the storm lasts longer."],adj=0.1)
    SA(t,'B',"A warm front moves in. What does warm air do as it overruns the cooler air ahead?",["rises","rise","slides up","rises over it","glides up","rises over the cold air"],["Warm air is less dense.","It rides up over the cold air, making broad cloud layers."])
    CP(t,'B',"The jet stream at 300 hPa is blowing FROM the west-southwest. Drag the pointer to that direction.",247,["West is 270° and southwest is 225°.","West-southwest is halfway between them: 247.5°."],tol=12)
    # ---------------- clouds: severe-weather clouds ----------------
    t='clouds'
    SA(t,'F',"What is the name for puffy, cotton-like clouds with flat bottoms?",["cumulus"],["Cumulus means heap or pile.","These are puffy clouds."])
    SA(t,'F',"What is the name for thin, wispy clouds high in the sky made of ice crystals?",["cirrus"],["Cirrus means a curl of hair.","These are the highest wispy clouds."])
    SA(t,'F',"What is the name for a flat, gray layer of cloud that covers the sky like a blanket?",["stratus"],["Stratus means layer.","Stratus often brings drizzle."])
    SA(t,'F',"Which cloud makes thunderstorms?",["cumulonimbus","cb"],["It grows tall with strong updrafts.","Cumulo means heap, nimbus means rain: a rain heap."])
    SA(t,'F',"The word nimbus on a cloud name means the cloud brings…",["rain","precipitation"],["Nimbus is Latin for rain cloud.","Nimbostratus and cumulonimbus bring precipitation."])
    SA(t,'F',"What do we call a cloud that touches the ground?",["fog"],["A cloud at ground level is fog.","It forms the same way as other clouds."])
    SA(t,'B',"The flat, spreading top of a thunderstorm is called an…",["anvil"],["Rising air hits a stable layer near the top of the troposphere.","It spreads sideways in the shape of an anvil."])
    SA(t,'B',"Which thunderstorm cloud has pouch-like bulges hanging from the underside of the anvil?",["mammatus","mammatus clouds"],["Sinking pockets of air form pouches.","They are mammatus clouds."])
    SA(t,'B',"A funnel cloud becomes a tornado when it…",["touches the ground","reaches the ground","touches down","contacts the ground"],["A funnel cloud hangs from the base of a storm.","When the rotating column reaches the ground it is a tornado."])
    SA(t,'B',"A long, low roll of cloud along the leading edge of a thunderstorm's cool outflow is called a(n)…",["shelf cloud","arcus cloud","arcus","roll cloud"],["Cool air from the storm pushes warm air up.","A shelf cloud forms on the gust front."],adj=0.1)
    SA(t,'B',"A lowered, rotating cloud base beneath a supercell's updraft is called a…",["wall cloud"],["The wall cloud forms under the main updraft.","Tornadoes often form from it."],adj=0.2)
    NM(t,'B',"A strong thunderstorm top reaches the tropopause at about 11 km. How many meters is that?",11000,["1 km = 1000 m.","11 × 1000 = 11,000 m."],u='m',free=True)
    OR(t,'B',"Put the cloud types in order from the lowest to the highest base height.",["Stratus (low)","Cumulus (low to middle)","Altocumulus (middle)","Cirrus (high)"],["Stratus clouds hug the ground.","Cumulus come next, altocumulus are mid-level, cirrus are highest."],adj=0.1)
    MT(t,'B',"Match each cloud feature to what it tells you.",[["Anvil","Top of a thunderstorm spreading out"],["Wall cloud","Rotating lowered base under a supercell"],["Shelf cloud","Gust front pushing warm air up"],["Mammatus","Pouches under an anvil"]],["Each feature has a typical position in a storm.","Learn them as a set when you read storm photos."])
